import{describe,it,expect}from"vitest";import{routes,ports,goods,filterPorts,filterRoutes,findPortById,getUniquePortsByRegion,getUniqueGoodsByCategory}from"../../frontend/trade-routes/trade-routes.js";const REQUIRED_ROUTE_FIELDS=["id","name","type","color","pathPoints","description","significance"],REQUIRED_PORT_FIELDS=["id","name","location","region","established","majorTradeWith","description","archaeologyFinds","image","coords"],REQUIRED_GOODS_FIELDS=["id","name","type","origin","description","icon"];describe("Trade Network Routes Data Integrity",()=>{it("contains at least 5 routes in the dataset",()=>{expect(routes.length).toBeGreaterThanOrEqual(5)}),it("every route contains all required fields with non-empty values",()=>{routes.forEach((e,t)=>{REQUIRED_ROUTE_FIELDS.forEach(o=>{expect(e,`Route at index ${t} missing field ${o}`).toHaveProperty(o),"pathPoints"===o?(expect(Array.isArray(e.pathPoints)).toBe(!0),expect(e.pathPoints.length).toBeGreaterThanOrEqual(2),e.pathPoints.forEach(e=>{expect(typeof e.x).toBe("number"),expect(typeof e.y).toBe("number"),expect(e.x).toBeGreaterThanOrEqual(0),expect(e.x).toBeLessThanOrEqual(900),expect(e.y).toBeGreaterThanOrEqual(0),expect(e.y).toBeLessThanOrEqual(600)})):(expect(typeof e[o]).toBe("string"),expect(e[o].trim().length).toBeGreaterThan(0))})})}),it("all route IDs are unique",()=>{const e=routes.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length)})}),describe("Trade Network Ports Data Integrity",()=>{it("contains at least 7 ports in the dataset",()=>{expect(ports.length).toBeGreaterThanOrEqual(7)}),it("every port contains all required fields with non-empty values",()=>{ports.forEach((e,t)=>{REQUIRED_PORT_FIELDS.forEach(o=>{expect(e,`Port at index ${t} missing field ${o}`).toHaveProperty(o),"coords"===o?(expect(typeof e.coords.x).toBe("number"),expect(typeof e.coords.y).toBe("number"),expect(e.coords.x).toBeGreaterThanOrEqual(0),expect(e.coords.x).toBeLessThanOrEqual(900),expect(e.coords.y).toBeGreaterThanOrEqual(0),expect(e.coords.y).toBeLessThanOrEqual(600)):(expect(typeof e[o]).toBe("string"),expect(e[o].trim().length).toBeGreaterThan(0))})})}),it("all port IDs and coordinates are unique",()=>{const e=ports.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length);const o=new Set(ports.map(e=>`${e.coords.x},${e.coords.y}`));expect(o.size).toBe(ports.length)})}),describe("Trade Network Goods Data Integrity",()=>{it("contains at least 8 trade goods in the dataset",()=>{expect(goods.length).toBeGreaterThanOrEqual(8)}),it("every trade good contains all required fields with valid values",()=>{goods.forEach((e,t)=>{REQUIRED_GOODS_FIELDS.forEach(o=>{expect(e,`Trade good at index ${t} missing field ${o}`).toHaveProperty(o),expect(typeof e[o]).toBe("string"),expect(e[o].trim().length).toBeGreaterThan(0)})})})}),describe("Trade Network Filtering & Search",()=>{it("returns all ports when search query and region are default",()=>{const e=filterPorts(ports);expect(e.length).toBe(ports.length)}),it("filters ports by search query (e.g. Rome or pepper)",()=>{const e=filterPorts(ports,{search:"Rome"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{const t=[e.name,e.location,e.region,e.majorTradeWith,e.description,e.archaeologyFinds].some(e=>e&&e.toLowerCase().includes("rome"));expect(t).toBe(!0)})}),it("filters ports by region (e.g. South)",()=>{const e=filterPorts(ports,{region:"South"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.region.toLowerCase()).toBe("south")})}),it("filters routes by land/maritime type",()=>{const e=filterRoutes(routes,"maritime");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.type).toBe("maritime"));const t=filterRoutes(routes,"land");expect(t.length).toBeGreaterThan(0),t.forEach(e=>expect(e.type).toBe("land"))}),it("returns empty array when search query matches no port",()=>{const e=filterPorts(ports,{search:"nonexistentport999"});expect(e.length).toBe(0)}),it("handles invalid inputs gracefully",()=>{expect(filterPorts(null)).toEqual([]),expect(filterPorts(void 0)).toEqual([]),expect(filterPorts([])).toEqual([]),expect(filterRoutes(null)).toEqual([])})}),describe("Trade Network Utilities & Lookups",()=>{it("finds port by ID correctly",()=>{const e=findPortById("muziris");expect(e).toBeDefined(),expect(e.name).toContain("Muziris")}),it("extracts unique regions from ports",()=>{const e=getUniquePortsByRegion(ports);expect(e.length).toBeGreaterThan(0),expect(e).toContain("South"),expect(e).toContain("West"),expect(e).toContain("East")}),it("extracts unique categories from goods",()=>{const e=getUniqueGoodsByCategory(goods);expect(e.length).toBeGreaterThan(0),expect(e).toContain("export"),expect(e).toContain("import")})});